    94      // 3. lag on react navigation transitions, see issue: https://github.com/Expensify/App/issues/44812
    95      if (
    96          hasNavigatedAway ||
    97          isError ||
    98          appState.isBackground ||
    99          !animationFile ||
   100          splashScreenState !== CONST.BOOT_SPLASH_STATE.HIDDEN ||
